<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref,watch,nextTick } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { getCurrentWindow } from '@tauri-apps/api/window';
import { listen,type UnlistenFn } from '@tauri-apps/api/event';
import { Monitor,Server,Terminal,Plus,ArrowRight,FolderOpen,MoreHorizontal,FileText,Power,LoaderCircle,X,PlugZap,Download,HardDrive,TriangleAlert } from '@lucide/vue';
import {profilePayload,type Profile} from './connections';
import Fish from './workbench/Fish.vue';
type Snapshot={profiles:Profile[];defaultHome:string;logs:string;dataRoot:string;installed:boolean;dataBesideProgram:boolean;portableNotice:boolean;overlayNotice:boolean;programName:string;active:string|null;version:string;notice:string|null};
type UpdateInfo={version:string;notes:string;installable:boolean};
const state=ref<Snapshot>({profiles:[],defaultHome:'',logs:'',dataRoot:'',installed:false,dataBesideProgram:true,portableNotice:false,overlayNotice:false,programName:'',active:null,version:'0.2.6',notice:null});
const update=ref<UpdateInfo|null>(null),updating=ref(''),checking=ref(false);
const form=reactive<Profile>({id:'',name:'本机管理',kind:'local',home:'',url:'',target:'',remotePort:18080});
const busy=ref(false),status=ref(''),error=ref(false),menu=ref(''),dialog=ref('');
const active=computed(()=>state.value.profiles.find(p=>p.id===state.value.active));
const selected=ref('');const listeners:UnlistenFn[]=[];
const modes=[{id:'local',label:'本机管理',icon:Monitor},{id:'remote',label:'管理地址',icon:Server},{id:'ssh',label:'SSH 连接',icon:Terminal}];
const descriptions={local:'在这台电脑上整理整合包、检查改动和发布版本。',remote:'连接已经运行的管理端，继续维护服务器上的项目。',ssh:'沿用系统 OpenSSH 配置，通过安全转发连接远程管理端。'};
function message(text:string,failed=false){status.value=text;error.value=failed;}
async function attempt(work:()=>Promise<unknown>){try{await work();}catch(e){message(String(e),true);}}
async function refresh(){state.value=await invoke<Snapshot>('load_desktop');if(state.value.notice)message(state.value.notice,true);}
function newProfile(kind:'local'|'remote'|'ssh'='local'){selected.value='';Object.assign(form,{id:'',name:kind==='local'?'本机管理':'我的服务器',kind,home:state.value.defaultHome,url:'',target:'',remotePort:18080});menu.value='';message('');}
function edit(profile:Profile){selected.value=profile.id;Object.assign(form,{home:'',url:'',target:'',remotePort:18080,...profile,confirmRelocation:false});menu.value='';message('');}
async function connect(profile:Profile){if(busy.value)return;busy.value=true;message(profile.kind==='local'?'正在启动本机管理端…':profile.kind==='ssh'?'正在建立 SSH 连接…':'正在连接管理端…');try{const saved=await invoke<Profile>('save_profile',{profile:profilePayload(profile)});await invoke('connect_profile',{id:saved.id});selected.value=saved.id;form.id=saved.id;await refresh();message('工作区已打开');}catch(e){message(String(e),true);}finally{busy.value=false;}}
async function remove(profile:Profile){busy.value=true;try{await invoke('delete_profile',{id:profile.id});if(selected.value===profile.id)newProfile();await refresh();message('已移除连接记录');}catch(e){message(String(e),true);}finally{busy.value=false;menu.value='';}}
async function chooseHome(){const path=await invoke<string|null>('choose_home');if(path){form.home=path;form.confirmRelocation=true;}}
async function disconnect(){busy.value=true;try{await invoke(dialog.value==='quit'?'quit_application':'disconnect_workspace');await refresh();message('工作区已断开');}catch(e){message(String(e),true);}finally{dialog.value='';busy.value=false;}}
async function quit(){if(active.value)dialog.value='quit';else await invoke('quit_application');}
async function dismissNotice(name:'portable'|'overlay'){await invoke('dismiss_notice',{name});if(name==='portable')state.value.portableNotice=false;else state.value.overlayNotice=false;}
// Checks quietly on launch; the footer button checks on request and reports the result.
async function checkUpdate(manual=false){if(checking.value)return;checking.value=true;try{update.value=await invoke<UpdateInfo|null>('check_update');if(manual&&!update.value)message(`已是最新版本 ${state.value.version}`);}catch(e){if(manual)message(String(e),true);}finally{checking.value=false;}}
async function startUpdate(){if(!update.value)return;if(!update.value.installable){await invoke('open_release_page');return;}if(active.value){dialog.value='update';return;}await runUpdate();}
async function runUpdate(){dialog.value='';updating.value='正在下载新版本…';busy.value=true;const stop=await listen<{received:number;total:number|null}>('update-progress',e=>{const {received,total}=e.payload;updating.value=total?`正在下载新版本 ${Math.min(100,Math.round(received/total*100))}%`:'正在下载新版本…';});try{await invoke('install_update');updating.value='正在安装，完成后会自动重新打开';}catch(e){updating.value='';message(String(e),true);}finally{stop();busy.value=false;}}
watch(dialog,value=>{if(value)void nextTick(()=>document.querySelector<HTMLButtonElement>('.native-dialog footer button')?.focus());});
function key(event:KeyboardEvent){if(!dialog.value)return;if(event.key==='Escape'&&!busy.value)dialog.value='';if(event.key==='Tab'){const buttons=[...document.querySelectorAll<HTMLButtonElement>('.native-dialog button:not(:disabled)')];if(event.shiftKey&&document.activeElement===buttons[0]){event.preventDefault();buttons.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===buttons.at(-1)){event.preventDefault();buttons[0]?.focus();}}}
onMounted(()=>{window.addEventListener('keydown',key);document.documentElement.dataset.theme=localStorage.getItem('dfs-desktop-theme')||'light';void attempt(async()=>{await refresh();newProfile();setTimeout(()=>void checkUpdate(),1500);listeners.push(await getCurrentWindow().onFocusChanged(e=>{if(e.payload&&!busy.value)void attempt(refresh);}));listeners.push(await listen('workspace-ended',()=>void attempt(refresh)));});});
onUnmounted(()=>{listeners.forEach(remove=>remove());window.removeEventListener('keydown',key);});
</script>
<template><main class="connection-library"><aside class="connection-sidebar"><header><span>管理连接</span><button class="icon-button" aria-label="新建连接" :disabled="busy" @click="newProfile()"><Plus :size="17"/></button></header><p class="connection-sidebar-note">选择本机或远程工作区</p><div class="saved-list"><article v-for="profile in state.profiles" :key="profile.id" :class="{selected:selected===profile.id}"><button class="connection-pick" :disabled="busy" @click="edit(profile)"><component :is="profile.kind==='local'?Monitor:profile.kind==='ssh'?Terminal:Server" :size="19"/><div><strong>{{profile.name}}</strong><small>{{profile.kind==='local'?'本机管理':profile.kind==='ssh'?profile.target:'远程管理端'}}</small></div><span v-if="profile.id===state.active" class="small-dot"/></button><button class="icon-button" :aria-label="`编辑连接 ${profile.name}`" :disabled="busy" @click="menu=menu===profile.id?'':profile.id"><MoreHorizontal :size="16"/></button><div v-if="menu===profile.id" class="connection-menu"><button :disabled="busy" @click="edit(profile)">编辑连接</button><button :disabled="busy||profile.id===state.active" @click="attempt(()=>remove(profile))">移除连接记录</button></div></article><div v-if="!state.profiles.length" class="connection-empty"><Monitor :size="26"/><span>还没有连接</span><small>从右侧打开第一个管理端</small></div></div><footer><button :disabled="busy" :title="state.dataRoot" @click="attempt(()=>invoke('open_data_dir'))"><HardDrive :size="14"/>数据目录</button><button :disabled="busy" @click="attempt(()=>invoke('open_logs'))"><FileText :size="14"/>运行日志</button><button :disabled="busy" @click="attempt(quit)"><Power :size="14"/>退出桌面端</button><button class="version-line" :disabled="busy||checking" title="检查更新" @click="attempt(()=>checkUpdate(true))">{{checking?'正在检查更新…':`桌面版 ${state.version} · ${state.installed?'安装版':'便携版'}`}}</button></footer></aside>
 <section class="connection-editor"><header class="connection-editor-header"><span>工作区</span><span class="subtle">{{selected?'编辑连接':'新建连接'}}</span></header><div class="connection-editor-scroll"><div v-if="state.portableNotice" class="portable-card" role="note"><HardDrive :size="18"/><div><strong>便携版的数据就在当前文件夹里</strong><small>连接记录和默认的项目数据保存在 {{state.dataRoot}}。请不要删除或单独移走这个 data 文件夹，换位置时连同程序文件夹一起复制。</small></div><button class="small" @click="attempt(()=>dismissNotice('portable'))">知道了</button></div><div v-if="state.overlayNotice" class="portable-card" role="note"><TriangleAlert :size="18"/><div><strong>检测到 RivaTuner（RTSS）帧数显示</strong><small>RTSS 会往本程序里注入帧数显示，可能让界面黑屏或崩溃；出问题时桌面端会自动重新打开窗口。想彻底避免，请在 RTSS 里点“Add”添加 {{state.programName||'本程序'}} 和 msedgewebview2.exe，并把它们的 Application detection level 设为 None。</small></div><button class="small" @click="attempt(()=>dismissNotice('overlay'))">知道了</button></div><div v-if="update" class="update-card"><Download :size="18"/><div><strong>可以更新到 {{update.version}}</strong><small>{{updating||(update.installable?'更新后自动重新打开，连接记录和项目数据都会保留。':'便携版请下载新的压缩包，替换程序文件即可，data 文件夹里的数据会保留。')}}</small></div><button class="accent small" :disabled="busy||!!updating" @click="attempt(startUpdate)">{{update.installable?'立即更新':'下载新版'}}</button></div><div v-if="active" class="running-connection"><span class="small-dot"/><div><strong>{{active.name}}</strong><small>工作区正在运行</small></div><button class="accent small" :disabled="busy" @click="attempt(()=>invoke('show_workspace'))">返回工作区 <ArrowRight :size="14"/></button><button class="icon-button" title="断开工作区" aria-label="断开工作区" :disabled="busy" @click="dialog='disconnect'"><X :size="16"/></button></div>
  <div class="connection-form-heading"><span class="overline"><Fish :size="15"/>DREAMINGFISH WORKSPACE</span><h1>{{selected?form.name:'从一个连接开始'}}</h1><p>{{selected?'修改连接信息，或打开这个工作区。':'本机的整合包、服务器上的项目，都在同一个桌面里维护。'}}</p></div><nav class="connection-tabs" aria-label="连接方式"><button v-for="item in modes" :key="item.id" :disabled="busy" :class="{active:form.kind===item.id}" @click="form.kind=item.id as Profile['kind'];message('')"><component :is="item.icon" :size="15"/>{{item.label}}</button></nav>
  <form class="connection-form" @submit.prevent="connect(form)"><p class="connection-description">{{descriptions[form.kind]}}</p><label>连接名称<input v-model="form.name" maxlength="60" required :disabled="busy" autocomplete="off"><small>只用来在左侧列表里区分不同的管理端，起一个好认的名字即可，例如“本机管理”或“生存服”。</small></label><template v-if="form.kind==='local'"><label>管理数据目录<div class="field-with-button"><input v-model="form.home" required :disabled="busy" autocomplete="off"><button type="button" title="选择目录" aria-label="选择管理数据目录" :disabled="busy" @click="attempt(chooseHome)"><FolderOpen :size="16"/></button></div><small>管理端在这里保存项目记录、签名密钥和已发布的文件，请定期备份。它不是整合包目录，一般保持默认位置即可（程序文件夹里的 data，卸载和升级都会保留）；要换位置，请选一个空文件夹，或以前用过的管理端目录（里面的项目和发布记录会继续使用）。</small><small v-if="!state.dataBesideProgram" class="data-note">程序所在文件夹不能写入，桌面端的数据改存在 {{state.dataRoot}}。</small></label></template><template v-else-if="form.kind==='remote'"><label>管理端地址<input v-model="form.url" type="url" placeholder="https://admin.example.com/" required :disabled="busy" autocomplete="off"><small>也可以使用已有的本机转发地址。</small></label></template><template v-else><label>SSH 配置名称或 user@host<input v-model="form.target" placeholder="例如 my-server" required :disabled="busy" autocomplete="off"></label><label>远程管理端口<input v-model.number="form.remotePort" type="number" min="1" max="65535" required :disabled="busy"></label><small class="ssh-note">使用系统 OpenSSH 的配置、密钥与已知主机记录。</small></template><div class="connection-form-actions"><button class="accent" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="15"/><ArrowRight v-else :size="16"/>{{busy?'正在连接…':form.kind==='local'?'打开工作区':'连接工作区'}}</button><button v-if="busy" type="button" @click="attempt(()=>invoke('cancel_connect'))">取消连接</button><span v-if="selected&&!busy">信息将在连接时保存</span></div><p v-if="status" class="connection-status" :class="{error}" role="status" aria-live="polite">{{status}}</p></form>
  <div class="connection-bottom-note"><PlugZap :size="17"/><span>关闭窗口会收到托盘，工作区可以随时回来。</span></div>
 </div></section><div v-if="dialog" class="modal-backdrop" @click.self="!busy&&(dialog='')"><section class="native-dialog" role="dialog" aria-modal="true"><header><h2>{{dialog==='quit'?'退出桌面端？':dialog==='update'?'关闭工作区并更新？':'断开当前工作区？'}}</h2></header><p>{{dialog==='update'?'更新会关闭当前工作区并停止本机管理端，安装完成后桌面端会自动重新打开。':'本机管理会停止所属服务；远程连接会断开，服务器继续运行。'}}</p><footer><button :disabled="busy" @click="dialog=''">取消</button><button class="accent" :disabled="busy" @click="attempt(dialog==='update'?runUpdate:disconnect)">{{dialog==='quit'?'退出桌面端':dialog==='update'?'关闭并更新':'确认断开'}}</button></footer></section></div></main></template>
